伪代码：preadv2 位置模式分流
position = if offset == -1 { None }
           else if offset >= 0 { Some(offset as u64) }
           else { return EINVAL }

match position:
    None    → file.read_into(target)       // 使用并推进共享游标
    Some(p) → file.read_at_into(p, target) // 显式位置，不动共享游标

